{
  "packet_id": "H6-T01-3",
  "claim_id": "C051",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C051.component",
    "value": "If poor source access undermines a disputed feature, that feature should no longer be treated as established.",
    "scope": "Conditional withdrawal of established status; the mapping gives no access-quality threshold.",
    "provenance": {
      "refs": [
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P032 explicitly identifies undermining poor access as grounds for withdrawing established status."
    }
  },
  "signal_basis": {
    "component_id": "C051.signal_basis",
    "value": "Assess who observed the feature and whether the source had direct access; the assessment reveals poor access that undermines the disputed feature's evidential support.",
    "scope": "Applies to the specific disputed feature when access deficiencies undermine its support, rather than whenever access is imperfect.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P032",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P009 supplies the access assessment, and P032 supplies the relevant undermining condition."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C051.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its explicit condition; no unresolved empirical relation is required."
    }
  },
  "rationale": "When poor access undermines the evidence for a disputed feature, withdrawing established status is warranted. This withdrawal does not establish that the feature is false.",
  "uncertainty": "The mapping provides no access-quality threshold, but the claim expressly requires that poor access undermine the feature's support.",
  "anomalies": []
}
